package com.intermarche.backoffice.engine.supervision;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.fieldops.FieldIncident;import com.intermarche.backoffice.domain.fieldops.MissionOperationalState;import com.intermarche.backoffice.domain.stock.QualityCase;import com.intermarche.backoffice.domain.inventory.InventoryCountSession;import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.printing.PrintJob;import com.intermarche.backoffice.domain.store.Store;import java.time.LocalDateTime;import java.util.*;
/** Shared read-only dossiers: same source identity in general and handling supervision. */
final class OperationalDiagnostics {
 static final int LIMIT=200;
 record Case(String id,String domain,String title,String detail,String action,String actionLabel,Long subjectId,Long handlingOrderId,Long productId,Long customerOrderId,LocalDateTime since,boolean blocking,Map<String,Object> context){}
 record Result(List<Case> cases,boolean limited){}
 static Result load(Store store){var result=new ArrayList<Case>();boolean limited=false;
 var incidents=FieldIncident.<FieldIncident>find("select i from FieldIncident i left join fetch i.handlingOrder left join fetch i.product where i.store=?1 and i.state in ('OPEN','OWNED','WAITING') order by i.createdAt,i.id",store).range(0,LIMIT).list();limited|=incidents.size()>LIMIT;
 for(var i:incidents.stream().limit(LIMIT).toList())result.add(new Case("incident:"+i.id,"INCIDENTS",i.title,i.comment,"OPEN_INCIDENT","Examiner le dossier",i.id,id(i.handlingOrder),id(i.product),null,i.createdAt,"SAFETY".equals(i.kind),Map.of("incidentId",i.id,"sourceState",i.state)));
 var waiting=MissionOperationalState.<MissionOperationalState>find("select m from MissionOperationalState m join fetch m.handlingOrder o where m.store=?1 and m.state<>'ACTIVE' and o.status in ('OPEN','SCHEDULED','PROCESSING','FAILED') order by m.updatedAt,m.id",store).range(0,LIMIT).list();limited|=waiting.size()>LIMIT;
 for(var m:waiting.stream().limit(LIMIT).toList())result.add(new Case("mission-state:"+m.id,"HANDLING","Mission "+("WAITING".equals(m.state)?"en attente":"en pause")+" · "+m.handlingOrder.code,m.reason,"OPEN_ORDER","Examiner la mission",m.id,id(m.handlingOrder),null,null,m.updatedAt,false,Map.of("orderId",id(m.handlingOrder),"orderKind",HandlingSupervisionService.kind(m.handlingOrder),"sourceState",m.state)));
 var quality=QualityCase.<QualityCase>find("select q from QualityCase q join fetch q.product where q.store=?1 and q.state='ACTIVE' order by q.createdAt,q.id",store).range(0,LIMIT).list();limited|=quality.size()>LIMIT;
 for(var q:quality.stream().limit(LIMIT).toList())result.add(new Case("quality:"+q.id,"QUALITY",("RECALL".equals(q.kind)?"Rappel":"Blocage qualité")+" · "+q.product.name,q.reason,"OPEN_QUALITY_CASE","Tracer les marchandises",q.id,null,id(q.product),null,q.createdAt,true,Map.of("qualityCaseId",q.id,"sourceState",q.state)));
 var inventories=InventoryCountSession.<InventoryCountSession>find("select c from InventoryCountSession c join fetch c.handlingOrder o where o.store=?1 and c.state in ('RECOUNT_REQUIRED','DISPUTED','SUBMITTED','APPROVED') order by c.createdAt,c.id",store).range(0,LIMIT).list();limited|=inventories.size()>LIMIT;
 for(var c:inventories.stream().limit(LIMIT).toList())result.add(new Case("inventory:"+c.id,"INVENTORY","Inventaire à arbitrer · "+c.handlingOrder.code,switch(c.state){case"RECOUNT_REQUIRED"->"Un recomptage indépendant est demandé.";case"DISPUTED"->"Les observations restent contradictoires : arbitrage requis.";case"APPROVED"->"Le comptage est approuvé, la correction reste à appliquer.";default->"Le comptage est soumis pour contrôle.";},"OPEN_INVENTORY_SESSION","Examiner le comptage",c.id,id(c.handlingOrder),null,null,c.submittedAt==null?c.createdAt:c.submittedAt,"DISPUTED".equals(c.state),Map.of("sessionId",c.id,"sourceState",c.state)));
 var returns=ProductReturn.<ProductReturn>find("select r from ProductReturn r where r.store=?1 and r.state<>'CLOSED' and exists(select l.id from ProductReturnLine l where l.productReturn=r and l.inspection='PENDING') order by r.createdAt,r.id",store).range(0,LIMIT).list();limited|=returns.size()>LIMIT;
 for(var r:returns.stream().limit(LIMIT).toList())result.add(new Case("return:"+r.id,"RETURNS","Retour à inspecter · "+r.code,r.reason,"OPEN_RETURN","Inspecter le retour",r.id,null,null,null,r.receivedAt==null?r.createdAt:r.receivedAt,false,Map.of("returnId",r.id,"sourceState",r.state)));
 var departures=LogisticsDeparture.<LogisticsDeparture>find("select d from LogisticsDeparture d join fetch d.order where d.store=?1 and d.state in ('LOADING','PARTIALLY_HANDED_OVER') order by d.createdAt,d.id",store).range(0,LIMIT).list();limited|=departures.size()>LIMIT;
 for(var d:departures.stream().limit(LIMIT).toList())result.add(new Case("departure:"+d.id,"SHIPPING","Départ à terminer · "+d.code,d.transportReference+" → "+d.recipient,"OPEN_DEPARTURE","Examiner le chargement",d.id,null,null,id(d.order),d.createdAt,false,Map.of("departureId",d.id,"sourceState",d.state)));
 var printing=PrintJob.<PrintJob>find("store=?1 and state in ('FAILED','UNKNOWN') order by createdAt,id",store).range(0,LIMIT).list();limited|=printing.size()>LIMIT;
 for(var j:printing.stream().limit(LIMIT).toList())result.add(new Case("print:"+j.id,"PRINTING","Impression à vérifier · "+j.logisticsCode,"UNKNOWN".equals(j.state)?"Résultat incertain : vérifiez l’étiquette physique avant une réimpression.":"Transmission échouée après les tentatives prévues.","OPEN_PRINT_JOB","Examiner l’impression",j.id,null,null,null,j.createdAt,false,Map.of("printJobId",j.id,"sourceState",j.state)));
 return new Result(List.copyOf(result),limited);
 }
}
